// Map (provider, status_code, body) -> (severity, cause, action).
// Provider-aware so we can surface provider-specific error vocabulary.

const inp = $json;
const provider = (inp.provider || 'Unknown').trim();
const sub = (inp.sub_provider || '').trim();
const status = Number(inp.status_code || 0);
const body = String(inp.error_body || '').slice(0, 300);
const ctx = inp.context || '';

let severity = 'warn';
let cause = 'Unknown error';
let action = 'Check the latest n8n execution for details.';

// Network / timeout (no status code surfaced)
if (!status || status === 0) {
  severity = 'warn';
  cause = 'Network timeout or connection failure.';
  action = 'Transient. If it keeps happening, check n8n container network and the provider status page.';
}
// 401 / 403 auth
else if (status === 401 || status === 403) {
  severity = 'critical';
  cause = `${provider} rejected the request as unauthorized (${status}).`;
  action = `Rotate and update the ${provider.toLowerCase()} API key/token in docker-compose.yml, then docker compose up -d.`;
}
// 402 payment required (credits out)
else if (status === 402) {
  severity = 'critical';
  cause = `${provider} billing: credits exhausted (402 Payment Required).`;
  action = `Top up ${provider} balance. The pipeline will keep failing until the account is funded.`;
}
// 429 rate limit
else if (status === 429) {
  severity = 'warn';
  cause = `${provider} rate-limited the request (429).`;
  action = 'Transient. n8n retry usually handles it. If it persists, reduce batch sizes or move to a higher plan.';
}
// 529 Anthropic overloaded
else if (status === 529) {
  severity = 'warn';
  cause = 'Anthropic is temporarily overloaded (529).';
  action = 'Transient on their side. Retry in a few minutes.';
}
// 5xx provider outage
else if (status >= 500 && status < 600) {
  severity = 'warn';
  cause = `${provider} returned a server error (${status}).`;
  action = `Likely a ${provider} outage. Check their status page; retries should recover automatically.`;
}
// 400 bad request
else if (status === 400) {
  severity = 'critical';
  cause = `${provider} rejected the request as malformed (400).`;
  action = 'Likely a workflow bug (wrong field name, missing required param, stale actor input schema). Check the error body below.';
}
// Monday-specific: 200 with errors array
else if (provider === 'Monday' && /"errors"/.test(body)) {
  severity = 'critical';
  cause = 'Monday returned a GraphQL error despite HTTP 200.';
  action = 'Check the error body. Common causes: stale column id, unknown group id, column_values shape mismatch.';
}

const providerLabel = sub ? `${provider} (${sub})` : provider;
const emoji = severity === 'critical' ? ':rotating_light:' : ':warning:';
const title = `${emoji} *${providerLabel} failure* — ${cause}`;
const text = `${title}\n\n*Workflow*: ${inp.workflow_name || 'unknown'}\n*Node*: ${inp.node_name || 'unknown'}\n*Context*: ${ctx || '-'}\n*HTTP*: ${status || 'no status'}\n*Action*: ${action}\n${body ? '\n*Response body (first 300 chars)*:\n```' + body + '```' : ''}`;

return [{ json: {
  channel: $env.SLACK_ALERT_CHANNEL_ID,
  text,
  _severity: severity,
  _cause: cause,
  _action: action,
  _provider_label: providerLabel
}}];
